mapper.select:
SELECT 
FROM learning_task task
JOIN language_profile profile ON profile.id = task.language_profile_id
WHERE task.id = #{taskId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}

UPDATE learning_task
SET status = 'STARTED',
    started_at = CURRENT_TIMESTAMP
WHERE id = #{taskId, jdbcType=OTHER}
  AND user_id = #{trustedUserId, jdbcType=OTHER}
  AND language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND status = 'PLANNED'
RETURNING id

UPDATE learning_task
SET status = 'COMPLETED',
    completed_at = CURRENT_TIMESTAMP
WHERE id = #{taskId, jdbcType=OTHER}
  AND user_id = #{trustedUserId, jdbcType=OTHER}
  AND language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND status = 'STARTED'
RETURNING id
